, addresses_flat TEXT NOT NULL DEFAULT '', phones_normalized TEXT NOT NULL DEFAULT '', sort_name TEXT NOT NULL DEFAULT '', is_favorite INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1);

CREATE TABLE activities (
