    status     TEXT NOT NULL CHECK (status IN ('ok', 'failed', 'error')),
    detail     TEXT NOT NULL DEFAULT '',
    checked_at DATETIME NOT NULL,
    created_at DATETIME,
    updated_at DATETIME
);

CREATE TABLE system_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at DATETIME NOT NULL,
    occurred_at DATETIME NOT NULL,
    event_type TEXT NOT NULL CHECK (event_type IN (
        'application_started', 'application_stopped',
        'migration_started', 'migration_completed', 'migration_failed',
        'job_started', 'job_completed', 'job_failed',
        'sync_started', 'sync_completed', 'sync_failed',
        'notification_sent', 'notification_failed',
        'backup_completed', 'backup_failed', 'restore_test_completed',
        'integration_failed'
    )),
    severity TEXT NOT NULL DEFAULT 'info' CHECK (severity IN ('info', 'warn', 'error')),
    component TEXT NOT NULL DEFAULT '',
    operation TEXT NOT NULL DEFAULT '',
    duration_ms INTEGER,
    result TEXT CHECK (result IS NULL OR result IN ('success', 'failure', 'skipped')),
    correlation_id TEXT NOT NULL DEFAULT '',
    error TEXT NOT NULL DEFAULT '',
    detail TEXT NOT NULL DEFAULT '',
    user_id INTEGER
);

CREATE TABLE alert_states (
    condition_key    TEXT PRIMARY KEY,
    state            TEXT NOT NULL CHECK (state IN ('ok', 'alerting')),
    since            DATETIME NOT NULL,
    detail           TEXT NOT NULL DEFAULT '',
    failure_count    INTEGER NOT NULL DEFAULT 0,
    last_notified_at DATETIME,
    created_at       DATETIME,
    updated_at       DATETIME
);

CREATE TABLE job_runs (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at      DATETIME NOT NULL,
    job_name        TEXT NOT NULL,
    trigger         TEXT NOT NULL DEFAULT 'scheduled'
                      CHECK (trigger IN ('scheduled', 'initial', 'manual')),
    started_at      DATETIME NOT NULL,
    finished_at     DATETIME NOT NULL,
    duration_ms     INTEGER NOT NULL,
    result          TEXT NOT NULL CHECK (result IN ('success', 'failure', 'skipped')),
    error           TEXT NOT NULL DEFAULT '',
    items_processed INTEGER,
    detail          TEXT NOT NULL DEFAULT '',
    correlation_id  TEXT NOT NULL DEFAULT ''
);

CREATE TABLE storage_samples (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    taken_at            DATETIME NOT NULL,
    database_bytes      INTEGER NOT NULL,
    fs_used_bytes       INTEGER NOT NULL,
    fs_total_bytes      INTEGER NOT NULL,
    photo_dir_bytes     INTEGER NOT NULL DEFAULT 0,
    attachment_dir_bytes INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE import_source_links (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at DATETIME,
    updated_at DATETIME,
    user_id INTEGER NOT NULL,
    system TEXT NOT NULL,
    external_id TEXT NOT NULL,
    entity_kind TEXT NOT NULL,
    entity_uid TEXT NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE "import_runs" (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id         INTEGER NOT NULL,
    format          TEXT NOT NULL CHECK (format IN ('csv', 'vcf', 'jscontact', 'records', 'monica', 'meerkat')),
    total_processed INTEGER NOT NULL DEFAULT 0,
    created         INTEGER NOT NULL DEFAULT 0,
    updated         INTEGER NOT NULL DEFAULT 0,
    skipped         INTEGER NOT NULL DEFAULT 0,
    error_count     INTEGER NOT NULL DEFAULT 0,
    created_at      DATETIME NOT NULL
);

CREATE TABLE idempotency_keys (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id             INTEGER NOT NULL,
    idempotency_key     TEXT NOT NULL,
    method              TEXT NOT NULL,
    path                TEXT NOT NULL,
    request_fingerprint TEXT NOT NULL,
    state               TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'completed')),
    response_status     INTEGER NOT NULL DEFAULT 0,
    response_body       TEXT NOT NULL DEFAULT '',
    created_at          DATETIME NOT NULL,
    updated_at          DATETIME NOT NULL
);

CREATE TABLE device_grants (
    id           INTEGER  PRIMARY KEY AUTOINCREMENT,
    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    deleted_at   DATETIME,
    user_id      INTEGER  NOT NULL,
    token_hash   TEXT     NOT NULL UNIQUE,
    label        TEXT     NOT NULL DEFAULT '',
    last_used_at DATETIME,
    revoked_at   DATETIME,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE data_backfills (
    name         TEXT     PRIMARY KEY,
    version      INTEGER  NOT NULL,
    completed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE sessions (
    id           TEXT     PRIMARY KEY,       -- 32 random bytes, base64url; = JWT "sid" claim
    user_id      INTEGER  NOT NULL,
    created_at   DATETIME NOT NULL,
    last_seen_at DATETIME NOT NULL,          -- advanced (throttled) on each authenticated request
    expires_at   DATETIME NOT NULL,          -- created_at + JWT_EXPIRY_HOURS (absolute ceiling)
    revoked_at   DATETIME,                   -- logout / password or 2FA change / manual revoke
    user_agent   TEXT     NOT NULL DEFAULT '',
    ip           TEXT     NOT NULL DEFAULT '',
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

